(window.MSHUB=window.MSHUB||{}).runbooks=[{"id":"rb-account-compromise","kind":"runbook","title":"Account compromise: contain and clean up","level":"L2","subject":"defender","verified":"2026-08","tags":["bec","compromise","containment","incident response"],"related":["scenario-compromise","ensign","enidp","dere","exrules","ps-block-user","ps-revoke-sessions","ps-inbox-rules-user"],"pre":["Authentication Administrator or higher for credential actions, Security Administrator for mail actions.","Agree who owns communications before you start; containment is visible to the user."],"steps":["Block sign-in for the account and revoke its refresh tokens; do both, because a password reset alone leaves live sessions.","Reset the password, and require change at next sign-in.","Review registered authentication methods and remove anything the user does not recognise, then re-register with a Temporary Access Pass.","Hunt persistence in the mailbox: list inbox rules and remove attacker rules, and check for forwarding addresses at mailbox, remote domain and transport rule level.","Check application consent: look for OAuth grants the user approved during the incident and revoke them.","Trace what was sent from the account during the exposure window and identify recipients who may have been phished onward.","Purge malicious mail sent internally, and submit external samples to Microsoft.","Review sign-in logs for the source IP and other accounts hit from it; repeat containment for any that match.","Confirm the device used is healthy in Defender before restoring access.","Restore access: unblock sign-in, confirm the user can sign in with the new credentials and methods."],"verify":["Risk state for the user is dismissed or remediated, and no new risky sign-ins appear.","No inbox rules or forwarding remain that the user did not create.","The account no longer appears in restricted entities for outbound spam."],"rollback":["If you blocked the wrong account, unblock sign-in and let the user re-authenticate; revoked tokens simply force a fresh sign-in."],"escalate":["Mailbox data was exfiltrated or a payment process was targeted: this is an incident, not a ticket.","Multiple accounts are affected, or an admin account is involved.","Persistence keeps returning after cleanup, which suggests a compromised device or app identity."]},{"id":"rb-bitlocker-key","kind":"runbook","title":"Find a BitLocker recovery key","level":"L1","subject":"intune","verified":"2026-08","tags":["bitlocker","recovery key","encryption"],"related":["endevices","enlaps","ps-bitlocker-keys","in-lapspolicy"],"pre":["Cloud Device Administrator, Intune Administrator, or Helpdesk Administrator depending on the path you use.","Verify the caller's identity before reading out a key; this is a full disk unlock."],"steps":["Ask the user for the key ID shown on the recovery screen: the first eight characters are enough to match.","Open the device in Entra devices, or in Intune device properties, and read the recovery keys section.","Match the key ID from the screen to the listed key, then read out the 48-digit key in blocks.","If the device is not listed, check whether it was ever escrowed: a device encrypted before policy applied may hold keys only locally or in on-prem AD.","If the user is self-service capable, point them at their own device list instead of reading the key out."],"verify":["The user boots into Windows after entering the key.","Confirm the device reports as encrypted and compliant after the next check-in."],"rollback":["Nothing to roll back for a read. If the key was exposed to the wrong person, rotate it."],"escalate":["No key exists for a device that policy says should be encrypted: the escrow path is broken and other devices are likely affected too.","The device is not recognised by the tenant at all, which may indicate a personal or rogue device."]},{"id":"rb-mail-not-arriving","kind":"runbook","title":"Mail not arriving: trace it end to end","level":"L1","subject":"m365","verified":"2026-08","tags":["message trace","mail flow","delivery"],"related":["exmt","deqre","detallow","exforwarding","ps-message-trace"],"pre":["Exchange Administrator or Exchange Recipient Administrator (read is enough to trace).","Ask the user for: sender address, expected recipient, rough time, and subject."],"steps":["Confirm the service is healthy first: check Service health for Exchange Online, so you do not debug a known incident.","Open Message trace and search on recipient plus a time window that brackets the reported send.","Read the status column: Delivered, Filtered as spam, Quarantined, Failed, or Pending.","If nothing is listed at all, the message never reached the service: verify the sender actually sent it and check the sender domain's MX and SPF records.","If Quarantined, open Quarantine, inspect the message, and release it only if it is legitimate.","If Filtered, open the message detail to see which policy acted, then decide policy tuning or a Tenant Allow entry with an expiry.","If Failed, read the NDR code in the detail view: 5.1.x means recipient/address, 5.7.x means policy or authentication.","If Delivered but the user cannot see it, check for an inbox rule or forwarding that moved it."],"verify":["The message shows Delivered to the mailbox and the user confirms they can see it.","If you released from quarantine, re-trace to confirm final delivery."],"rollback":["If you added a Tenant Allow entry, remove it once the root cause is fixed; allow entries weaken filtering.","If you disabled an inbox rule, note the rule contents before deleting so the user can rebuild it."],"escalate":["The trace shows Pending for more than an hour with no service health advisory.","Mail is failing for an entire domain rather than one recipient.","You suspect compromise: an unexplained inbox rule or forwarding address means switch to the account compromise runbook."]}];
